    /// <summary>The colours a member taken into the party at the inn starts with: both the shared palette and the slot's.</summary>
    // orig: R038+0x02F8 (1462:02F8) draft key 0x1E41 (the new member), checked against asm: all 24 bytes of both
    public static IReadOnlyList<byte> InnStartPalette { get; } =
    [
        0x39, 0x36, 0x00, 0x3D, 0x38, 0x15, 0x00, 0x18, 0x28, 0x00, 0x11, 0x25,
        0x00, 0x15, 0x25, 0x1C, 0x00, 0x00, 0x17, 0x00, 0x00, 0x11, 0x00, 0x00,
    ];

    /// <summary>The shared figure palette (DS:E753..DS:E76A).</summary>
    public byte[] Palette { get; } = new byte[24];

    /// <summary>The step of key 1 (DS:E890), key 2 (DS:E892) and key 3 (DS:E894), 0..5.</summary>
    public int FirstStep => _steps[1];

    public int SecondStep => _steps[2];

    public int ThirdStep => _steps[3];

    private readonly int[] _steps = new int[4];

    /// <summary>Key 1, 2 or 3 on a member with figure <paramref name="image"/>: the next colour set; other figures: nothing.</summary>
    public void Cycle(int key, string image, byte[] memberPalette) => Cycle(Branches, key, image, memberPalette);

    /// <summary>The same in the inn's roster, with that screen's tables.</summary>
    public void CycleAtInn(int key, string image, byte[] memberPalette) => Cycle(InnBranches, key, image, memberPalette);

    private void Cycle(Branch[] table, int key, string image, byte[] memberPalette)
    {
        var branch = Array.Find(table, b => b.Key == key && b.Image == image);
        if (branch is null)
        {
            return;
        }
        if (++_steps[branch.Counter] >= 6)
        {
            _steps[branch.Counter] = 0;
        }
        foreach (var (index, value) in branch.Steps[_steps[branch.Counter]])
        {
            Palette[index] = value;
        }
        foreach (var (member, shared) in branch.Copies)
        {
            memberPalette[member] = Palette[shared];
        }
    }

    /// <summary>Selecting a party member loads its palette into the shared one (the arrow keys).</summary>
    // orig: R037+0x0444 cases 0x4800/0x4B00/0x4D00 and 0x5000: DS:E753..DS:E76A = member_palette[il][0..23]
    public void Load(byte[] memberPalette) => memberPalette.CopyTo(Palette, 0);
}
